/* ============================================================
   Serie A 2026/27 - 38 Haftalik Ornek Veri Seti (MSSQL)
   Uretim: tools/generate_seed_sql.py  (deterministik)
   - 1-20. haftalar: OYNANMIS (skor + istatistik + gol olaylari)
   - 21-38. haftalar: OYNANMAMIS (fikstur cekilmis, 0-0)
   - 20. haftanin son maci: Pazar 27.09.2026 21:45
   NOT: Takimlar (20 adet) zaten ekli olmalidir; Id'ler isimden cozulur.
   ============================================================ */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;

-- 1) Mevcut mac verilerini temizle (Teams korunur). FK sirasina dikkat.
DELETE FROM MatchEvents;
DELETE FROM MatchStatics;
DELETE FROM PlayerCareers;
DELETE FROM Fixtures;
DELETE FROM Players;
DELETE FROM Stadiums;
DBCC CHECKIDENT ('Fixtures', RESEED, 0);
DBCC CHECKIDENT ('MatchEvents', RESEED, 0);
DBCC CHECKIDENT ('MatchStatics', RESEED, 0);
DBCC CHECKIDENT ('Players', RESEED, 0);
DBCC CHECKIDENT ('PlayerCareers', RESEED, 0);
DBCC CHECKIDENT ('Stadiums', RESEED, 0);

-- 2) Takim Id'leri (isimden cozulur)
DECLARE @Atalanta INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Atalanta');
DECLARE @Bologna INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Bologna');
DECLARE @Cagliari INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Cagliari');
DECLARE @Como INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Como');
DECLARE @Fiorentina INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Fiorentina');
DECLARE @Frosinone INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Frosinone');
DECLARE @Genoa INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Genoa');
DECLARE @Inter INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Inter');
DECLARE @Juventus INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Juventus');
DECLARE @Lazio INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Lazio');
DECLARE @Lecce INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Lecce');
DECLARE @Milan INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Milan');
DECLARE @Monza INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Monza');
DECLARE @Napoli INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Napoli');
DECLARE @Parma INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Parma');
DECLARE @Roma INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Roma');
DECLARE @Sassuolo INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Sassuolo');
DECLARE @Torino INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Torino');
DECLARE @Udinese INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Udinese');
DECLARE @Venezia INT = (SELECT TeamId FROM Teams WHERE TeamName = N'Venezia');

-- Takimlarin ekli oldugunu dogrula
IF (@Atalanta IS NULL OR @Bologna IS NULL OR @Cagliari IS NULL OR @Como IS NULL OR @Fiorentina IS NULL OR @Frosinone IS NULL OR @Genoa IS NULL OR @Inter IS NULL OR @Juventus IS NULL OR @Lazio IS NULL OR @Lecce IS NULL OR @Milan IS NULL OR @Monza IS NULL OR @Napoli IS NULL OR @Parma IS NULL OR @Roma IS NULL OR @Sassuolo IS NULL OR @Torino IS NULL OR @Udinese IS NULL OR @Venezia IS NULL)
BEGIN
    RAISERROR('Takimlar bulunamadi. Once 20 Serie A takimini ekleyin, sonra bu script i calistirin.', 16, 1);
    ROLLBACK TRANSACTION;
    RETURN;
END

